import math
from typing import List, Tuple, Optional


class Calculator:
    """
    This is a class for a calculator, capable of performing basic arithmetic calculations on numerical expressions
    using the operators +, -, *, /, and ^ (exponentiation).
    """

    def __init__(self):
        """
        Initialize the operations performed by the five operators '+', '-', '*', '/', '^'
        """
        self.operators = {
            '+': lambda x, y: x + y,
            '-': lambda x, y: x - y,
            '*': lambda x, y: x * y,
            '/': lambda x, y: x / y,
            '^': lambda x, y: x ** y,
        }

    def calculate(self, expression: str) -> Optional[float]:
        """
        Calculate the value of a given expression.
        Supports +, -, *, /, ^ and parentheses. Numbers may contain decimal points.
        Whitespace is ignored.

        :param expression: string, given expression
        :return: If successful, returns the value of the expression; otherwise, returns None
        """
        if not expression:
            return None

        operand_stack: List[float] = []
        operator_stack: List[str] = []
        num_buffer = ""

        def flush_number():
            nonlocal num_buffer
            if num_buffer:
                try:
                    operand_stack.append(float(num_buffer))
                except ValueError:
                    return False
                num_buffer = ""
            return True

        for ch in expression:
            if ch.isspace():
                continue
            if ch.isdigit() or ch == '.':
                num_buffer += ch
            elif ch in self.operators:
                if not flush_number():
                    return None
                # Handle unary minus (negative numbers)
                if ch == '-' and (not operand_stack and (not operator_stack or operator_stack[-1] == '(')):
                    num_buffer = '-'
                    continue
                while (
                    operator_stack
                    and operator_stack[-1] != '('
                    and self.precedence(operator_stack[-1]) >= self.precedence(ch)
                ):
                    operand_stack, operator_stack = self.apply_operator(
                        operand_stack, operator_stack
                    )
                    if operand_stack is None:
                        return None
                operator_stack.append(ch)
            elif ch == '(':
                if not flush_number():
                    return None
                operator_stack.append(ch)
            elif ch == ')':
                if not flush_number():
                    return None
                # Pop until matching '('
                while operator_stack and operator_stack[-1] != '(':
                    operand_stack, operator_stack = self.apply_operator(
                        operand_stack, operator_stack
                    )
                    if operand_stack is None:
                        return None
                if not operator_stack or operator_stack[-1] != '(':
                    # Mismatched parentheses
                    return None
                operator_stack.pop()  # Remove '('
            else:
                # Invalid character
                return None

        if not flush_number():
            return None

        # Apply remaining operators
        while operator_stack:
            if operator_stack[-1] == '(' or operator_stack[-1] == ')':
                return None  # Mismatched parentheses
            operand_stack, operator_stack = self.apply_operator(
                operand_stack, operator_stack
            )
            if operand_stack is None:
                return None

        return operand_stack[-1] if operand_stack else None

    def precedence(self, operator: str) -> int:
        """
        Returns the priority of the specified operator, where the higher the priority, the greater the assignment.
        The priority of '^' is greater than '/' and '*', and the priority of '/' and '*' is greater than '+' and '-'.

        :param operator: string, given operator
        :return: int, the priority of the given operator, otherwise return 0
        """
        precedences = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
        return precedences.get(operator, 0)

    def apply_operator(
        self, operand_stack: List[float], operator_stack: List[str]
    ) -> Tuple[List[float], List[str]]:
        """
        Use the operator at the top of the operator stack to perform the operation on the two numbers at the top of the operand stack,
        and store the results at the top of the operand stack.

        :param operand_stack: list of operands
        :param operator_stack: list of operators
        :return: the updated operand_stack and operator_stack
        """
        if not operator_stack or len(operand_stack) < 2:
            return None, None

        operator = operator_stack.pop()
        try:
            operand2 = operand_stack.pop()
            operand1 = operand_stack.pop()
            result = self.operators[operator](operand1, operand2)
        except ZeroDivisionError:
            return None, None
        except Exception:
            return None, None

        operand_stack.append(result)
        return operand_stack, operator_stack
