    based on input data. MRR measures the ranking quality, while MAP measures the average precision.
    """

    def __init__(self):
        pass

    @staticmethod
    def mrr(data):
        """
        Compute the MRR of the input data. MRR is the mean of reciprocal ranks.

        Parameters
        ----------
        data : tuple or list
            A single tuple of the form (predictions, ground_truth_count) where
            predictions is an iterable of 0/1 values indicating correctness.
            Or a list of such tuples.

        Returns
        -------
        tuple
            (mean_mrr, [mrr_for_each_tuple])
        """
        # Validate input type
        if not isinstance(data, (list, tuple)):
            raise Exception(
                "the input must be a tuple([0,...,1,...],int) or an iterable of such tuples"
            )

        # Handle empty input
        if isinstance(data, list) and len(data) == 0:
            return (0.0, [0.0])

        # Helper to compute MRR for a single tuple
        def _mrr_single(sub_list, total_num):
            sub_list = np.asarray(sub_list, dtype=int)
            if total_num == 0 or sub_list.size == 0:
                return 0.0
            # Find first index where prediction is 1
            idx = np.argmax(sub_list == 1)
