import numpy as np


class MetricsCalculator2:
    """
    The class provides methods to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP)
    based on input data. MRR measures the ranking quality and MAP measures the average precision.
    """

    def __init__(self):
        pass

    @staticmethod
    def mrr(data):
        """
        Compute the MRR of the input data. MRR is the mean of reciprocal rank.

        Parameters
        ----------
        data : tuple or list
            The data must be a tuple (actual_result, ground_truth_num) or a list of such tuples.
            `actual_result` is a list/tuple of 0/1 values where 1 indicates a correct answer.
            `ground_truth_num` is the total number of relevant items.

        Returns
        -------
        tuple
            (mrr_value, [mrr_value]) for a single tuple input,
            or (mean_mrr, [mrr_value_1, mrr_value_2, ...]) for a list of tuples.

        Examples
        --------
        >>> MetricsCalculator2.mrr(([1, 0, 1, 0], 4))
        (1.0, [1.0])
        >>> MetricsCalculator2.mrr([([1, 0, 1, 0], 4), ([0, 1, 0, 1], 4)])
        (0.75, [1.0, 0.5])
        """
        if type(data) not in (list, tuple):
            raise Exception('the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple')
        if len(data) == 0:
            return (0.0, [0.0])

        # Single tuple case
        if isinstance(data, tuple):
            sub_list, total_num = data
            sub_list = np.array(sub_list)
            if total_num == 0:
                return (0.0, [0.0])
            ranking_array = 1.0 / (np.arange(len(sub_list)) + 1)
            mr_np = sub_list * ranking_array
            mr = 0.0
            for val in mr_np:
                if val > 0:
                    mr = val
                    break
            return (mr, [mr])

        # List of tuples case
        separate_result = []
        for sub_list, total_num in data:
            sub_list = np.array(sub_list)
            if total_num == 0:
                mr = 0.0
            else:
                ranking_array = 1.0 / (np.arange(len(sub_list)) + 1)
                mr_np = sub_list * ranking_array
                mr = 0.0
                for val in mr_np:
                    if val > 0:
                        mr = val
                        break
            separate_result.append(mr)
        return (np.mean(separate_result), separate_result)

    @staticmethod
    def map(data):
        """
        Compute the MAP of the input data. MAP is the mean of average precision.

        Parameters
        ----------
        data : tuple or list
            The data must be a tuple (actual_result, ground_truth_num) or a list of such tuples.
            `actual_result` is a list/tuple of 0/1 values where 1 indicates a correct answer.
            `ground_truth_num` is the total number of relevant items.

        Returns
        -------
        tuple
            (map_value, [map_value]) for a single tuple input,
            or (mean_map, [ap_value_1, ap_value_2, ...]) for a list of tuples.

        Examples
        --------
        >>> MetricsCalculator2.map(([1, 0, 1, 0], 4))
        (0.41666666666666663, [0.41666666666666663])
        >>> MetricsCalculator2.map([([1, 0, 1, 0], 4), ([0, 1, 0, 1], 4)])
        (0.3333333333333333, [0.41666666666666663, 0.25])
        """
        if type(data) not in (list, tuple):
            raise Exception('the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple')
        if len(data) == 0:
            return (0.0, [0.0])

        # Single tuple case
        if isinstance(data, tuple):
            sub_list, total_num = data
            sub_list = np.array(sub_list)
            if total_num == 0:
                return (0.0, [0.0])
            ranking_array = 1.0 / (np.arange(len(sub_list)) + 1)
            right_ranking_list = []
            count = 1
            for t in sub_list:
                if t == 0:
                    right_ranking_list.append(0)
                else:
                    right_ranking_list.append(count)
                    count += 1
            ap = np.sum(np.array(right_ranking_list) * ranking_array) / total_num
            return (ap, [ap])

        # List of tuples case
        separate_result = []
        for sub_list, total_num in data:
            sub_list = np.array(sub_list)
            if total_num == 0:
                ap = 0.0
            else:
                ranking_array = 1.0 / (np.arange(len(sub_list)) + 1)
                right_ranking_list = []
                count = 1
                for t in sub_list:
                    if t == 0:
                        right_ranking_list.append(0)
                    else:
                        right_ranking_list.append(count)
                        count += 1
                ap = np.sum(np.array(right_ranking_list) * ranking_array) / total_num
            separate_result.append(ap)
        return (np.mean(separate_result), separate_result)

