from typing import Match

class NumericEntityUnescaper:
    """
    This class provides functionality to replace numeric entities with their corresponding characters in a given string.
    """

    # Regular expressions for decimal and hexadecimal numeric character references
    _DECIMAL_RE = re.compile(r'&#(\d+);')
    _HEXADECIMAL_RE = re.compile(r'&#x([0-9a-fA-F]+);')

    def __init__(self):
        pass

    def replace(self, string: str) -> str:
        """
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.

        :param string: str, the input string containing numeric character references.
        :return: str, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'
        """
        if not string:
            return string

        # First replace hexadecimal references
        def _hex_replacer(match: Match[str]) -> str:
            hex_value = match.group(1)
            try:
                code_point = int(hex_value, 16)
                return chr(code_point)
            except (ValueError, OverflowError):
                # If conversion fails, return the original match unchanged
                return match.group(0)

        result = self._HEXADECIMAL_RE.sub(_hex_replacer, string)

        # Then replace decimal references
        def _dec_replacer(match: Match[str]) -> str:
            dec_value = match.group(1)
            try:
                code_point = int(dec_value, 10)
                return chr(code_point)
            except (ValueError, OverflowError):
                return match.group(0)

        result = self._DECIMAL_RE.sub(_dec_replacer, result)

        return result

    @staticmethod
    def is_hex_char(char: str) -> bool:
